style.css:
@-moz-document domain("roblox.com") {
body {
    background: url("https://i.imgur.com/nupp9Th.jpeg") no-repeat center center fixed !important;
    background-size: cover !important;
    background-color: #fce4ec !important;
    color: #660033 !important;
  }

  *, *::before, *::after {
    color: #660033 !important;
    background-color: rgba(255, 240, 245, 0.8) !important;
    border-color: #ffb6c1 !important;
  }

  a {
    color: #cc3366 !important;
    text-decoration: underline !important;
  }

  .btn, .button, button {
    background-color: #ffc0cb !important;
    color: #660033 !important;
    border: 1px solid #ff69b4 !important;
  }

  h1, h2, h3, h4 {
    color: #cc3366 !important;
    font-weight: bold !important;
  }

  .content, .main-container, #navigation, .sidebar {
    backdrop-filter: blur(4px) !important;
    background-color: rgba(255, 240, 245, 0.6) !important;
  }
}
